export type ViewType = 'home' | 'services' | 'team' | 'privacy' | 'terms' | 'cookies' | 'trust' | 'how-it-works' | 'faq';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewType>('home');
  const [pendingHash, setPendingHash] = useState<string | null>(null);
  const [isTourActive, setIsTourActive] = useState(false);

  const handleNavigate = (view: ViewType, hash?: string) => {
    setCurrentView(view);
    if (hash) {
      setPendingHash(hash);
    } else {
      setPendingHash(null);
    }
  };

  useEffect(() => {
    if (currentView === 'home' && pendingHash) {
      const element = document.querySelector(pendingHash);
      if (element) {
        const timeoutId = setTimeout(() => {
          element.scrollIntoView({ behavior: 'smooth' });
          setPendingHash(null);
        }, 100);
        return () => clearTimeout(timeoutId);
      }
    }
  }, [currentView, pendingHash]);

  const startTour = () => {
    if (currentView !== 'home') {
      setCurrentView('home');
      setTimeout(() => setIsTourActive(true), 100);
    } else {
      setIsTourActive(true);
    }
  };

  const renderHome = () => (
    <div className="relative overflow-x-hidden w-full">
      <Hero onNavigate={handleNavigate} onStartTour={startTour} />

      {/* Dynamic Background Atmosphere - Layered Glows */}
